/**
 * build.mjs — the SCF documentation site.
 *
 *   npm run build      write site/dist
 *   npm run check      build to a temp dir and verify; write nothing
 *
 * WHAT THIS DOES NOT DO.
 *
 * It authors nothing. Every page is a Markdown file that already exists
 * in the repository and is already reviewed, checksummed or generated by
 * something else. A documentation site that carried its own copy of the
 * specification would be the same defect this project keeps finding —
 * one thing described in two places, drifting — except with the drifting
 * copy on the internet.
 *
 * The one exception is `index.md`, which is the landing page and is
 * meant to be written by a person. It is the only file here with
 * content of its own.
 *
 * WHAT IT ADDS, AND WHY IT IS WORTH A BUILD STEP.
 *
 * §-REFERENCES BECOME LINKS. The specification cross-references itself
 * constantly — "(§12.1.2)", "spec §6.6.1", "§4.5 pattern 2" — and in
 * plain Markdown every one of those is dead text, and a reader
 * implementing from this document navigates it by scrolling.
 *
 * AND A DANGLING REFERENCE FAILS THE BUILD. Resolving them means
 * knowing which sections exist, which means knowing when one does not.
 * A `§9.7` in prose when §9 stops at §9.6 is a defect a reader finds by
 * losing ten minutes; here it stops CI. That check is the reason this
 * is a generator rather than a Jekyll config.
 */

import { marked } from "marked";
import {
  cpSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync,
} from "node:fs";
import { createHash } from "node:crypto";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..");
const CHECK = process.argv.includes("--check");

/**
 * A short hash of the stylesheet, added to its URL so a browser fetches
 * the new one after a deploy instead of reusing a cached copy that does
 * not match the new pages.
 */
const CSS_VERSION = createHash("sha256")
  .update(readFileSync(join(HERE, "style.css")))
  .digest("hex").slice(0, 10);
const OUT = CHECK ? mkdtempSync(join(tmpdir(), "scf-site-")) : join(HERE, "dist");

/**
 * The site, in nav order. `source` is repository-relative; nothing here
 * is written by this package except index.md.
 *
 * `anchors: true` marks a document whose own §N.N headings define
 * section numbers other documents may reference. Only the spec does.
 */
const PAGES = [
  { group: "", title: "Overview", slug: "index", source: "site/index.md",
    blurb: "What the format is" },

  { group: "The editor", title: "Quickstart",
    slug: "editor-quickstart", source: "docs/editor-quickstart.md",
    blurb: "Get going with the SCF Editor, tab by tab" },
  { group: "The editor", title: "Project",
    slug: "editor-project", source: "docs/editor-manual-project.md",
    blurb: "The Project tab, saving, file tabs, the menu and settings" },
  { group: "The editor", title: "Script",
    slug: "editor-script", source: "docs/editor-manual-script.md",
    blurb: "Writing, formatting and committing in the Script tab" },
  { group: "The editor", title: "Structure",
    slug: "editor-structure", source: "docs/editor-manual-structure.md",
    blurb: "Acts and sequences, and where each one starts" },
  { group: "The editor", title: "Shoot",
    slug: "editor-shoot", source: "docs/editor-manual-shoot.md",
    blurb: "Beats, shots, storyboards and frames" },
  { group: "The editor", title: "Characters",
    slug: "editor-characters", source: "docs/editor-manual-characters.md",
    blurb: "The character workspace, As of, boards and story strips" },
  { group: "The editor", title: "Locations & props",
    slug: "editor-locations-props",
    source: "docs/editor-manual-locations-props.md",
    blurb: "Variants, sound, prop states and script tags" },
  { group: "The editor", title: "Tools",
    slug: "editor-tools", source: "docs/editor-manual-tools.md",
    blurb: "Subjects, Queries, Schema, Assets and the event log" },
  { group: "The editor", title: "Presentation",
    slug: "editor-presentation", source: "docs/editor-manual-presentation.md",
    blurb: "Screenplay, storyboard, shot list and gallery, printed and shown" },

  { group: "Specification", title: "The specification",
    slug: "spec", source: "spec/scf-spec.md", anchors: true,
    blurb: "Normative. Everything the format requires" },
  { group: "Specification", title: "Conformance",
    slug: "conformance", source: "spec/conformance.md",
    blurb: "The three roles, and how a claim is made" },
  { group: "Specification", title: "Stability",
    slug: "stability", source: "spec/stability.md",
    blurb: "What is safe to build against" },
  { group: "Specification", title: "Changelog",
    slug: "changelog", source: "spec/CHANGELOG.md", historical: true,
    blurb: "Every revision, and why" },

  { group: "Reference", title: "Entities",
    slug: "entities", source: "spec/entity-reference.md",
    blurb: "All 99 entities and their fields. Generated" },
  { group: "Reference", title: "Queries",
    slug: "queries", source: "spec/query-reference.md",
    blurb: "The sixteen canonical queries. Generated" },
  { group: "Reference", title: "Published artifacts",
    slug: "artifacts", source: "spec/ARTIFACTS.md",
    blurb: "Addressable and checksummed. Generated" },

  { group: "Contributing", title: "How to contribute",
    slug: "contributing", source: "CONTRIBUTING.md",
    blurb: "Which of the three routes a change takes" },
  { group: "Contributing", title: "Proposals",
    slug: "proposals", source: "proposals/README.md",
    blurb: "Where a change to the format gets argued" },
  { group: "Contributing", title: "Governance",
    slug: "governance", source: "GOVERNANCE.md",
    blurb: "Who decides, and what they weigh" },
  { group: "Contributing", title: "Security",
    slug: "security", source: "SECURITY.md",
    blurb: "What is in scope, and how to report" },

  { group: "Understanding SCF", title: "What is SCF?",
    slug: "what-is-scf", source: "docs/what-is-scf.md",
    blurb: "Start here if the format is new to you" },
  { group: "Understanding SCF", title: "Walkthrough",
    slug: "walkthrough", source: "docs/walkthrough.md",
    blurb: "One worked example against a real file" },
  { group: "Understanding SCF", title: "Authoring guide",
    slug: "authoring-guide", source: "docs/authoring-guide.md",
    blurb: "What to fill in first, and what can wait" },
  { group: "Understanding SCF", title: "Glossary",
    slug: "glossary", source: "docs/glossary.md",
    blurb: "Plain-language definitions of the terms the spec assumes" },
  { group: "Understanding SCF", title: "FAQ",
    slug: "faq", source: "docs/faq.md",
    blurb: "What it is, what it is not, and whether to build on it" },

  { group: "Design record", title: "Why it is like this",
    slug: "conventions", source: "docs/conventions.md",
    blurb: "The design record. States no rules" },
  { group: "Design record", title: "Story structure",
    slug: "story-structure", source: "docs/story-structure-design-record.md",
    blurb: "Spans, boundaries and the shoot surface" },
  { group: "Design record", title: "Release checklist",
    slug: "release-checklist", source: "docs/release-checklist.md",
    blurb: "What stands between here and 1.0" },
];

/**
 * Brand files, copied from the CI collections under docs/ rather than
 * kept here: one copy of each logo, in the place the designers put it.
 * Keys are paths under dist/assets, values repository-relative sources.
 */
const ASSETS = {
  "scf-full-black.svg": "docs/SCF_CI_Collection/SVG/logoFull_black.svg",
  "scf-full-white.svg": "docs/SCF_CI_Collection/SVG/logoFull_white.svg",
  "mh-short.svg": "docs/MinimalHumans_CI_Collection/SVG/logoShort.svg",
  "favicon.ico": "docs/SCF_CI_Collection/favicon/favicon.ico",
  "favicon-16x16.png": "docs/SCF_CI_Collection/favicon/favicon-16x16.png",
  "favicon-32x32.png": "docs/SCF_CI_Collection/favicon/favicon-32x32.png",
  "apple-touch-icon.png": "docs/SCF_CI_Collection/favicon/apple-touch-icon.png",
};

/**
 * Image folders a page refers to, copied whole. The key is the path
 * under dist, and it matches the path relative to docs/, so a page's
 * `images/...` link works both on the site and when the Markdown is
 * read on GitHub.
 */
const IMAGE_DIRS = {
  "images/editor-quickstart": "docs/images/editor-quickstart",
  "images/editor-manual": "docs/images/editor-manual",
};

const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;")
  .replace(/>/g, "&gt;").replace(/"/g, "&quot;");

// ── Pass one: read every page, and learn which sections exist ────────
const docs = [];
const sections = new Map();   // "12.1.2" -> { slug, id, title }

for (const page of PAGES) {
  let text;
  try {
    text = readFileSync(join(ROOT, page.source), "utf8");
  } catch {
    console.error(`[site] missing source: ${page.source}`);
    process.exit(1);
  }
  // The SPDX comment is repository bookkeeping, not page content.
  text = text.replace(/^<!--\s*SPDX-License-Identifier:[^>]*-->\s*\n/, "");

  const headings = [];
  let fenced = false;
  for (const line of text.split("\n")) {
    // A "# …" line inside a code block is code, not a heading.
    if (/^\s*(```|~~~)/.test(line)) fenced = !fenced;
    if (fenced) continue;
    const m = /^(#{1,6})\s+(.+?)\s*$/.exec(line);
    if (!m) continue;
    const title = m[2].replace(/[`*]/g, "");
    const num = /^(\d+(?:\.\d+)*)\.?\s+/.exec(title);
    const id = num
      ? `s${num[1].replace(/\./g, "-")}`
      : title.toLowerCase().replace(/[^a-z0-9]+/g, "-")
        .replace(/^-|-$/g, "");
    headings.push({ level: m[1].length, title, id, number: num?.[1] ?? null });
    if (page.anchors && num) {
      sections.set(num[1], { slug: page.slug, id, title });
    }
  }
  docs.push({ page, text, headings });
}

// ── §-reference resolution ───────────────────────────────────────────
const dangling = [];

/**
 * Rewrite §N.N into a link, and record any that names no section.
 *
 * Deliberately narrow: only a `§` immediately followed by digits. Prose
 * says "section 9" and "§9.4 and §9.5" and "conformance.md §2.2", and
 * guessing at the looser forms would produce wrong links, which are
 * worse than none.
 *
 * A reference in a document OTHER than the spec still resolves against
 * the spec's sections, because that is what those documents mean by §.
 */
function linkSections(html, selfSlug, historical = false) {
  return html.replace(/§(\d+(?:\.\d+)*)/g, (whole, num) => {
    const hit = sections.get(num);
    if (hit === undefined) {
      // Trailing-punctuation case: "§9." is a reference to §9.
      const trimmed = num.replace(/\.$/, "");
      const alt = sections.get(trimmed);
      if (alt !== undefined) {
        const href = alt.slug === selfSlug ? `#${alt.id}`
          : `${alt.slug}.html#${alt.id}`;
        return `<a class="xref" href="${href}" title="${esc(alt.title)}">` +
               `§${trimmed}</a>.`;
      }
      // A CHANGELOG legitimately names sections that no longer exist:
      // §4.3.1 was added in 0.16 and deleted in 0.21, and both entries
      // are correct about the document as it stood. Recording history
      // is the one place a reference to something gone is not a defect.
      // Everywhere else it sends a reader looking for nothing.
      if (historical) return whole;
      dangling.push({ ref: `§${num}`, slug: selfSlug });
      return `<span class="xref-dead" title="no such section">${whole}</span>`;
    }
    const href = hit.slug === selfSlug ? `#${hit.id}`
      : `${hit.slug}.html#${hit.id}`;
    return `<a class="xref" href="${href}" title="${esc(hit.title)}">` +
           `${whole}</a>`;
  });
}

// ── Render ───────────────────────────────────────────────────────────
marked.use({
  renderer: {
    heading({ tokens, depth }) {
      const title = this.parser.parseInline(tokens);
      // Decode the entities marked emits ("&amp;", "&#39;") so the id
      // matches the one the contents list derives from the source text.
      const plain = title.replace(/<[^>]+>/g, "")
        .replace(/&#39;/g, "'").replace(/&quot;/g, '"')
        .replace(/&lt;/g, "<").replace(/&gt;/g, ">")
        .replace(/&amp;/g, "&");
      const num = /^(\d+(?:\.\d+)*)\.?\s+/.exec(plain);
      const id = num
        ? `s${num[1].replace(/\./g, "-")}`
        : plain.toLowerCase().replace(/[^a-z0-9]+/g, "-")
          .replace(/^-|-$/g, "");
      return `<h${depth} id="${id}">${title}` +
             `<a class="anchor" href="#${id}" aria-label="link">#</a>` +
             `</h${depth}>\n`;
    },
  },
});

function nav(currentSlug) {
  const groups = [];
  for (const page of PAGES) {
    let g = groups.find((x) => x.name === page.group);
    if (g === undefined) { g = { name: page.group, pages: [] }; groups.push(g); }
    g.pages.push(page);
  }
  return groups.map((g) => {
    const items = g.pages.map((p) =>
      `<li${p.slug === currentSlug ? ' class="here"' : ""}>` +
      `<a href="${p.slug}.html">${esc(p.title)}</a></li>`).join("");
    return (g.name ? `<h2>${esc(g.name)}</h2>` : "") + `<ul>${items}</ul>`;
  }).join("");
}

/** The landing page's masthead. Only index has one. */
function hero() {
  return `<header class="hero">
<h1 class="hero-mark">
<picture>
<source media="(prefers-color-scheme: dark)" srcset="assets/scf-full-white.svg">
<img src="assets/scf-full-black.svg" alt="SCF — Story Context Framework" width="440" height="129">
</picture>
</h1>
<p class="hero-lede">A film, described in a way a machine can answer questions about.</p>
<p class="hero-actions">
<a class="btn btn-primary" href="what-is-scf.html">What is SCF?</a>
<a class="btn" href="editor-quickstart.html">Editor quickstart</a>
<a class="btn" href="spec.html">Read the specification</a>
<a class="btn btn-ghost" href="https://github.com/MinimalHumans/scf">GitHub</a>
</p>
</header>`;
}

/**
 * On-page contents. Deep documents are unusable without one.
 *
 * A <details> so that it costs one line above the text on a narrow
 * screen; on a wide one it is a column of its own beside the text and
 * TOC_SCRIPT holds it open. Without script it is simply open.
 */
function contents(headings) {
  const useful = headings.filter((h) => h.level >= 2 && h.level <= 3);
  if (useful.length < 4) return "";
  const items = useful.map((h) =>
    `<li class="l${h.level}"><a href="#${h.id}">${esc(h.title)}</a></li>`)
    .join("");
  return `<details class="toc" open><summary>On this page</summary>` +
    `<nav aria-label="On this page"><ul>${items}</ul></nav></details>`;
}

/** Keep in step with the wide breakpoint in style.css. */
const TOC_SCRIPT = `<script>
(() => {
  const toc = document.querySelector(".toc");
  if (toc === null) return;
  const wide = matchMedia("(min-width: 75rem)");
  const sync = () => { toc.open = wide.matches; };
  sync();
  wide.addEventListener("change", sync);
  // On a narrow screen, get out of the way once a section is chosen.
  toc.addEventListener("click", (e) => {
    if (!wide.matches && e.target.closest("a") !== null) toc.open = false;
  });
  toc.querySelector("summary").addEventListener("click", (e) => {
    if (wide.matches) e.preventDefault();
  });
})();
</script>`;

const built = [];
for (const { page, text, headings } of docs) {
  const body = linkSections(marked.parse(text), page.slug,
                            page.historical === true);
  const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${page.slug === "index" ? "SCF — Story Context Framework" : `${esc(page.title)} — SCF`}</title>
<meta name="description" content="${esc(page.blurb)}">
<meta name="theme-color" content="#1b6393">
<link rel="icon" href="assets/favicon.ico" sizes="any">
<link rel="icon" type="image/png" sizes="32x32" href="assets/favicon-32x32.png">
<link rel="icon" type="image/png" sizes="16x16" href="assets/favicon-16x16.png">
<link rel="apple-touch-icon" href="assets/apple-touch-icon.png">
<link rel="stylesheet" href="style.css?v=${CSS_VERSION}">
</head>
<body>
<a class="skip" href="#content">Skip to content</a>
<div class="shell">
<aside class="side">
<a class="brand" href="index.html">
<img src="assets/scf-full-white.svg" alt="SCF — Story Context Framework" width="200" height="59">
</a>
${nav(page.slug)}
<p class="repo"><a href="https://github.com/MinimalHumans/scf">Repository on GitHub</a></p>
<a class="maker" href="https://www.minimalhumans.com" target="_blank" rel="noopener">
<span>Developed by</span>
<img src="assets/mh-short.svg" alt="Minimal Humans" width="150" height="49">
</a>
</aside>
<main id="content"${page.slug === "index" ? ' class="landing"' : ""}>
${contents(headings)}
<div class="page">
${page.slug === "index" ? hero() : ""}
<article>
${body}
</article>
<footer>
<p>Rendered from <code>${esc(page.source)}</code>. The repository is the
source of truth; if this page disagrees with it, the repository is right.</p>
<p class="credit">SCF is developed by <a href="https://www.minimalhumans.com">Minimal Humans</a>.</p>
</footer>
</div>
</main>
</div>
${TOC_SCRIPT}
</body>
</html>
`;
  built.push({ slug: page.slug, html });
}

// ── A dangling cross-reference is a defect, not a cosmetic problem ───
if (dangling.length > 0) {
  const seen = new Set();
  console.error("[site] cross-references that name no section:\n");
  for (const d of dangling) {
    const key = `${d.slug}:${d.ref}`;
    if (seen.has(key)) continue;
    seen.add(key);
    console.error(`  ${d.ref}  in ${d.slug}`);
  }
  console.error("\n  Either the section was renumbered and something still " +
                "points at the old\n  number, or the reference is a typo. " +
                "Both send a reader looking for\n  something that is not " +
                "there.");
  if (CHECK) rmSync(OUT, { recursive: true, force: true });
  process.exit(1);
}

rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });
for (const { slug, html } of built) {
  writeFileSync(join(OUT, `${slug}.html`), html, "utf8");
}
cpSync(join(HERE, "style.css"), join(OUT, "style.css"));
mkdirSync(join(OUT, "assets"), { recursive: true });
for (const [name, source] of Object.entries(ASSETS)) {
  cpSync(join(ROOT, source), join(OUT, "assets", name));
}
for (const [dest, source] of Object.entries(IMAGE_DIRS)) {
  cpSync(join(ROOT, source), join(OUT, dest), { recursive: true });
}
writeFileSync(join(OUT, ".nojekyll"), "", "utf8");

const summary = `${String(built.length)} pages, ` +
  `${String(sections.size)} linkable sections`;
if (CHECK) {
  rmSync(OUT, { recursive: true, force: true });
  console.log(`[site] builds clean (${summary}).`);
} else {
  console.log(`[site] wrote site/dist — ${summary}.`);
}
